package ru.admincontrol.client;
import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.client.texture.NativeImage;import net.minecraft.client.texture.NativeImageBackedTexture;import net.minecraft.text.Text;import net.minecraft.util.Identifier;import java.io.ByteArrayInputStream;import java.util.*;import java.util.function.Consumer;
public final class CwSkinPickerScreen extends Screen{
	public record Skin(String name,byte[] png){}private final Screen parent;private final List<Skin> skins;private final Consumer<String> selected;private final Map<String,Identifier> textures=new HashMap<>();private int scroll;private static final int COLS=5,ROWS=3,CELL_W=92,CELL_H=72;
	public CwSkinPickerScreen(Screen parent,List<Skin> skins,Consumer<String> selected){super(Text.literal("Выбор скина NPC"));this.parent=parent;this.skins=skins;this.selected=selected;}
	@Override protected void init(){for(Skin skin:skins)try{NativeImage image=NativeImage.read(new ByteArrayInputStream(skin.png));Identifier id=new Identifier("admin_control","skin_picker/"+Integer.toHexString(skin.name.hashCode()));client.getTextureManager().registerTexture(id,new NativeImageBackedTexture(image));textures.put(skin.name,id);}catch(Exception ignored){}addDrawableChild(ButtonWidget.builder(Text.literal("Назад"),b->close()).dimensions(width/2-50,height-28,100,20).build());}
	@Override public boolean mouseScrolled(double x,double y,double amount){scroll=Math.max(0,Math.min(Math.max(0,(skins.size()+COLS-1)/COLS-ROWS),scroll-(int)Math.signum(amount)));return true;}
	@Override public boolean mouseClicked(double mx,double my,int button){if(super.mouseClicked(mx,my,button))return true;int left=width/2-COLS*CELL_W/2,top=42,col=(int)((mx-left)/CELL_W),row=(int)((my-top)/CELL_H);if(col>=0&&col<COLS&&row>=0&&row<ROWS){int i=(scroll+row)*COLS+col;if(i<skins.size()){selected.accept(skins.get(i).name);if(client!=null)client.setScreen(parent);return true;}}return false;}
	@Override public void close(){if(client!=null)client.setScreen(parent);}@Override public boolean shouldPause(){return false;}@Override public void render(DrawContext c,int mx,int my,float d){renderBackground(c);c.drawCenteredTextWithShadow(textRenderer,title,width/2,14,0xFFFFD27A);int left=width/2-COLS*CELL_W/2,top=42;for(int row=0;row<ROWS;row++)for(int col=0;col<COLS;col++){int i=(scroll+row)*COLS+col,x=left+col*CELL_W,y=top+row*CELL_H;c.fill(x+2,y+2,x+CELL_W-3,y+CELL_H-3,0xDD202936);if(i<skins.size()){Skin skin=skins.get(i);Identifier tex=textures.get(skin.name);if(tex!=null){c.drawTexture(tex,x+30,y+7,8,8,32,32,64,64);c.drawTexture(tex,x+30,y+7,40,8,32,32,64,64);}c.drawCenteredTextWithShadow(textRenderer,skin.name,x+CELL_W/2,y+48,0xFFFFFFFF);}}if(skins.isEmpty())c.drawCenteredTextWithShadow(textRenderer,"Положите PNG 64×64 в mods/Skins",width/2,height/2,0xFFFF7777);super.render(c,mx,my,d);}
}
